/**
 * @canvas      Welcome — a single "Hello" artboard
 * @ds          maude
 * @platform    desktop
 * @artboards   hello
 */

import "../system/maude/colors_and_type.css";
import { DesignCanvas, DCSection, DCArtboard } from "@maude/canvas-lib";

export default function Welcome() {
  return (
    <DesignCanvas>
      <DCSection id="welcome" title="Welcome">
        <DCArtboard id="hello" label="Hello" width={800} height={500}>
          <div
            className="maude"
            data-theme="dark"
            style={{
              width: "100%",
              height: "100%",
              display: "grid",
              placeItems: "center",
              background: "var(--bg-1)",
              color: "var(--fg-0)",
            }}
          >
            <h1 style={{ margin: 0, fontFamily: "var(--font-display)", fontSize: 64, fontWeight: 600 }}>Hello</h1>
          </div>
        </DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}

